#!/usr/bin/env python3
"""
E23C — Materialização da rota seletiva BA-TOS.

Gate congelado, sem GT:
    median(region_voxels) <= 3
    AND
    q75(region_voxels) <= 4

Rota:
- gate falso  -> ToS MIN congelado;
- gate verdadeiro -> EDT-Otsu congelado.

O script não calcula métricas e não lê GT. Ele somente:
- calcula o gate nos marcadores ToS atuais;
- escolhe a fonte;
- copia o volume de marcadores escolhido;
- grava um manifesto reproduzível.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import platform
import shutil
import sys
from pathlib import Path

import numpy as np
import pandas as pd
import tifffile
from scipy import ndimage as ndi


CONNECTIVITY_6 = ndi.generate_binary_structure(3, 1)

GATE_NAME = "region_median_le3_and_q75_le4"
MEDIAN_LIMIT = 3.0
Q75_LIMIT = 4.0


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--candidate-diagnostics",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--tos-marker-csv",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--tos-marker-tiff",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--edt-marker-tiff",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--crop-id",
        type=str,
        required=True,
    )
    parser.add_argument(
        "--out-dir",
        type=Path,
        required=True,
    )
    # batos_v3 patch: gate limits exposed (defaults = frozen values)
    parser.add_argument("--v3-median-limit", type=float, default=MEDIAN_LIMIT)
    parser.add_argument("--v3-q75-limit", type=float, default=Q75_LIMIT)
    return parser.parse_args()


def require_file(path: Path, description: str) -> Path:
    resolved = path.expanduser().resolve()

    if not resolved.is_file():
        raise FileNotFoundError(f"{description}: {resolved}")

    return resolved


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()

    with path.open("rb") as handle:
        for block in iter(
            lambda: handle.read(1024 * 1024),
            b"",
        ):
            digest.update(block)

    return digest.hexdigest()


def sha256_array(array: np.ndarray) -> str:
    contiguous = np.ascontiguousarray(array)
    return hashlib.sha256(contiguous.tobytes()).hexdigest()


def read_marker_count(path: Path) -> tuple[int, tuple[int, ...], str]:
    array = np.asarray(tifffile.imread(path))
    array = np.squeeze(array)

    if array.ndim != 3:
        raise ValueError(
            f"Marcador precisa ser 3D: {path}, shape={array.shape}"
        )

    _, count = ndi.label(
        array > 0,
        structure=CONNECTIVITY_6,
    )

    return int(count), tuple(array.shape), sha256_array(array)


def compute_gate(
    diagnostics_path: Path,
    marker_csv_path: Path,
) -> dict[str, object]:
    diagnostics = pd.read_csv(diagnostics_path)
    markers = pd.read_csv(marker_csv_path)

    required_diagnostic = {
        "node",
        "region_voxels",
        "has_reconstructed_region",
    }
    required_marker = {"node"}

    missing_diagnostic = sorted(
        required_diagnostic - set(diagnostics.columns)
    )
    missing_marker = sorted(
        required_marker - set(markers.columns)
    )

    if missing_diagnostic:
        raise ValueError(
            "Diagnóstico sem colunas: "
            + ", ".join(missing_diagnostic)
        )

    if missing_marker:
        raise ValueError(
            "Marcadores sem colunas: "
            + ", ".join(missing_marker)
        )

    diagnostics = diagnostics.copy()
    markers = markers.copy()

    diagnostics["node"] = pd.to_numeric(
        diagnostics["node"],
        errors="raise",
    ).astype(np.int64)

    markers["node"] = pd.to_numeric(
        markers["node"],
        errors="raise",
    ).astype(np.int64)

    selected = markers[["node"]].merge(
        diagnostics,
        on="node",
        how="left",
        validate="one_to_one",
    )

    if selected["region_voxels"].isna().any():
        missing_nodes = selected.loc[
            selected["region_voxels"].isna(),
            "node",
        ].head(10).tolist()

        raise RuntimeError(
            "Nós selecionados ausentes no diagnóstico: "
            f"{missing_nodes}"
        )

    values = pd.to_numeric(
        selected["region_voxels"],
        errors="coerce",
    ).dropna()

    if values.empty:
        raise RuntimeError(
            "Sem region_voxels válidos para o gate."
        )

    median_value = float(values.median())
    q25_value = float(values.quantile(0.25))
    q75_value = float(values.quantile(0.75))

    triggered = bool(
        median_value <= MEDIAN_LIMIT
        and q75_value <= Q75_LIMIT
    )

    return {
        "gate_name": GATE_NAME,
        "gate_triggered": triggered,
        "region_voxels_q25": q25_value,
        "region_voxels_median": median_value,
        "region_voxels_q75": q75_value,
        "median_limit": MEDIAN_LIMIT,
        "q75_limit": Q75_LIMIT,
        "selected_tos_marker_rows": int(len(selected)),
    }


def main() -> int:
    global MEDIAN_LIMIT, Q75_LIMIT
    args = parse_args()
    MEDIAN_LIMIT, Q75_LIMIT = float(args.v3_median_limit), float(args.v3_q75_limit)

    diagnostics_path = require_file(
        args.candidate_diagnostics,
        "Diagnóstico espacial",
    )
    marker_csv_path = require_file(
        args.tos_marker_csv,
        "CSV dos marcadores ToS",
    )
    tos_tiff_path = require_file(
        args.tos_marker_tiff,
        "Marcador ToS",
    )
    edt_tiff_path = require_file(
        args.edt_marker_tiff,
        "Marcador EDT",
    )

    out_dir = args.out_dir.expanduser().resolve()
    out_dir.mkdir(parents=True, exist_ok=False)

    gate = compute_gate(
        diagnostics_path,
        marker_csv_path,
    )

    if bool(gate["gate_triggered"]):
        selected_source = "edt_otsu"
        selected_path = edt_tiff_path
    else:
        selected_source = "tos_e11_min"
        selected_path = tos_tiff_path

    tos_count, tos_shape, tos_array_hash = read_marker_count(
        tos_tiff_path
    )
    edt_count, edt_shape, edt_array_hash = read_marker_count(
        edt_tiff_path
    )
    selected_count, selected_shape, selected_array_hash = (
        read_marker_count(selected_path)
    )

    if tos_shape != edt_shape:
        raise RuntimeError(
            f"Shapes incompatíveis: ToS={tos_shape}, EDT={edt_shape}"
        )

    destination = out_dir / "batos_selective_markers_uint16.tif"
    shutil.copy2(selected_path, destination)

    copied_count, copied_shape, copied_array_hash = read_marker_count(
        destination
    )

    if copied_shape != selected_shape:
        raise RuntimeError(
            "Shape mudou durante a cópia do marcador."
        )

    if copied_count != selected_count:
        raise RuntimeError(
            "Número de componentes mudou durante a cópia."
        )

    if copied_array_hash != selected_array_hash:
        raise RuntimeError(
            "Hash do array mudou durante a cópia."
        )

    manifest = {
        "experiment": "E23C_selective_marker_router",
        "gt_used": False,
        "diagnostic_only": False,
        "crop_id": str(args.crop_id),
        "python": platform.python_version(),
        "gate": gate,
        "routing_rule": {
            "gate_false": "tos_e11_min",
            "gate_true": "edt_otsu",
        },
        "selected_source": selected_source,
        "selected_source_path": str(selected_path),
        "output_marker": str(destination),
        "source_marker_counts": {
            "tos_e11_min": tos_count,
            "edt_otsu": edt_count,
            "selected": selected_count,
        },
        "source_array_sha256": {
            "tos_e11_min": tos_array_hash,
            "edt_otsu": edt_array_hash,
            "selected": selected_array_hash,
            "copied_output": copied_array_hash,
        },
        "source_file_sha256": {
            "tos_e11_min": sha256_file(tos_tiff_path),
            "edt_otsu": sha256_file(edt_tiff_path),
            "selected": sha256_file(selected_path),
            "copied_output": sha256_file(destination),
        },
        "shape": list(selected_shape),
    }

    manifest_path = out_dir / "route_manifest.json"
    manifest_path.write_text(
        json.dumps(
            manifest,
            indent=2,
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    summary = pd.DataFrame(
        [
            {
                "crop": str(args.crop_id),
                "gate_triggered":
                    bool(gate["gate_triggered"]),
                "region_voxels_median":
                    float(gate["region_voxels_median"]),
                "region_voxels_q75":
                    float(gate["region_voxels_q75"]),
                "selected_source": selected_source,
                "selected_marker_count": selected_count,
                "selected_array_sha256":
                    selected_array_hash,
                "output_array_sha256":
                    copied_array_hash,
                "copy_verified":
                    selected_array_hash == copied_array_hash,
            }
        ]
    )

    summary.to_csv(
        out_dir / "route_summary.csv",
        index=False,
    )

    print(json.dumps(manifest, indent=2, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(
            f"[E23C][ERRO] {type(exc).__name__}: {exc}",
            file=sys.stderr,
        )
